UPDATE public.site_settings SET value = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(value, '{areas}', (value->'areas') - 'test'), '{cities}', (value->'cities') - 'test'), '{bhk_options}', (value->'bhk_options') - 'test'), '{listing_types}', (value->'listing_types') - 'test'), '{property_types}', (value->'property_types') - 'test'), '{popular_localities}', (value->'popular_localities') - 'test') WHERE key='search_filters';